CREATE TABLE tenants (
 id BIGSERIAL PRIMARY KEY, name VARCHAR(255) NOT NULL, type VARCHAR(20) NOT NULL CHECK(type IN ('SCHOOL','COLLEGE','UNIVERSITY','COACHING')),
 contact_email VARCHAR(100) UNIQUE NOT NULL, attendance_cutoff_time TIME NOT NULL DEFAULT '06:00', destination_lat DOUBLE PRECISION NOT NULL DEFAULT 33.6426, destination_lng DOUBLE PRECISION NOT NULL DEFAULT 72.993,
 timezone TEXT NOT NULL DEFAULT 'Asia/Karachi', plan TEXT NOT NULL DEFAULT 'Driver Pro', trip_time TIME NOT NULL DEFAULT '06:15', monthly_fee NUMERIC(10,2) NOT NULL DEFAULT 6500 CHECK(monthly_fee>=0),platform_commission_pct NUMERIC(5,2) NOT NULL DEFAULT 5 CHECK(platform_commission_pct BETWEEN 0 AND 100),demo_offset_minutes INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE users (
 id BIGSERIAL PRIMARY KEY,tenant_id BIGINT REFERENCES tenants(id) ON DELETE CASCADE,custom_id VARCHAR(50) UNIQUE NOT NULL,name VARCHAR(100) NOT NULL,phone VARCHAR(20),email VARCHAR(100),password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN ('SUPER_ADMIN','ADMIN','DRIVER','STUDENT')),fcm_token TEXT,active BOOLEAN NOT NULL DEFAULT true,token_version INTEGER NOT NULL DEFAULT 0,login_failures INTEGER NOT NULL DEFAULT 0,locked_until TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),CHECK((role='SUPER_ADMIN')=(tenant_id IS NULL))
);
CREATE TABLE driver_verifications (
 id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,driver_id BIGINT UNIQUE NOT NULL,cnic_number BYTEA NOT NULL,license_number VARCHAR(50) NOT NULL,license_expiry DATE NOT NULL,vehicle_reg_number VARCHAR(50) NOT NULL,cnic_photo_url TEXT,license_photo_url TEXT,vehicle_photo_url TEXT,status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','VERIFIED','REJECTED')),rejection_reason TEXT,reviewed_by BIGINT,verified_at TIMESTAMPTZ,FOREIGN KEY(tenant_id,driver_id) REFERENCES users(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,reviewed_by) REFERENCES users(tenant_id,id)
);
CREATE TABLE document_blobs (
 id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,driver_id BIGINT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('cnic','license','vehicle')),mime_type TEXT NOT NULL,contents BYTEA NOT NULL CHECK(octet_length(contents)<=2097180),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,driver_id,kind),FOREIGN KEY(tenant_id,driver_id) REFERENCES users(tenant_id,id) ON DELETE CASCADE
);
CREATE TABLE vehicles (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,reg_number VARCHAR(50) UNIQUE NOT NULL,capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 100),UNIQUE(tenant_id,id));
CREATE TABLE routes (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,name VARCHAR(100) NOT NULL,driver_id BIGINT,vehicle_id BIGINT,start_time TIME NOT NULL DEFAULT '06:15',direction VARCHAR(20) NOT NULL DEFAULT 'TO_CAMPUS' CHECK(direction IN('TO_CAMPUS','FROM_CAMPUS')),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,driver_id) REFERENCES users(tenant_id,id),FOREIGN KEY(tenant_id,vehicle_id) REFERENCES vehicles(tenant_id,id));
CREATE TABLE student_stops (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,student_id BIGINT UNIQUE NOT NULL,route_id BIGINT NOT NULL,stop_name VARCHAR(255) NOT NULL,latitude DOUBLE PRECISION NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude DOUBLE PRECISION NOT NULL CHECK(longitude BETWEEN -180 AND 180),FOREIGN KEY(tenant_id,student_id) REFERENCES users(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,route_id) REFERENCES routes(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE daily_attendance (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,student_id BIGINT NOT NULL,trip_date DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'GOING' CHECK(status IN('GOING','NOT_GOING')),boarded BOOLEAN NOT NULL DEFAULT false,visit_status TEXT NOT NULL DEFAULT 'Waiting',override_requested BOOLEAN NOT NULL DEFAULT false,requested_status TEXT CHECK(requested_status IN('GOING','NOT_GOING')),marked_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,student_id,trip_date),FOREIGN KEY(tenant_id,student_id) REFERENCES users(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE trips (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,route_id BIGINT NOT NULL,driver_id BIGINT NOT NULL,trip_date DATE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'IDLE' CHECK(status IN('IDLE','IN_PROGRESS','ARRIVED','COMPLETED')),started_at TIMESTAMPTZ,ended_at TIMESTAMPTZ,UNIQUE(tenant_id,id),UNIQUE(tenant_id,route_id,trip_date),FOREIGN KEY(tenant_id,route_id) REFERENCES routes(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,driver_id) REFERENCES users(tenant_id,id));
CREATE TABLE trip_events (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,trip_id BIGINT NOT NULL,student_id BIGINT,event_type VARCHAR(30) NOT NULL,latitude DOUBLE PRECISION,longitude DOUBLE PRECISION,speed_kmh DOUBLE PRECISION,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,trip_id) REFERENCES trips(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,student_id) REFERENCES users(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE fee_transactions (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,student_id BIGINT NOT NULL,period_month DATE NOT NULL,monthly_fee NUMERIC(10,2) NOT NULL,installation_fee NUMERIC(10,2) NOT NULL DEFAULT 0,platform_commission_pct NUMERIC(5,2) NOT NULL DEFAULT 0,net_driver_payout NUMERIC(10,2),status VARCHAR(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','PAID','FAILED')),gateway_ref VARCHAR(100) UNIQUE,receipt_url VARCHAR(255),receipt_number TEXT UNIQUE,paid_at TIMESTAMPTZ,payment_session TEXT UNIQUE,payment_session_expires TIMESTAMPTZ,UNIQUE(tenant_id,student_id,period_month),FOREIGN KEY(tenant_id,student_id) REFERENCES users(tenant_id,id) ON DELETE CASCADE);
CREATE TABLE sos_events (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,trip_id BIGINT NOT NULL,raised_by BIGINT NOT NULL,latitude DOUBLE PRECISION,longitude DOUBLE PRECISION,resolved BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,trip_id) REFERENCES trips(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,raised_by) REFERENCES users(tenant_id,id));
CREATE TABLE notifications (id BIGSERIAL PRIMARY KEY,tenant_id BIGINT NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,user_id BIGINT NOT NULL,trip_id BIGINT,kind TEXT NOT NULL,message TEXT NOT NULL,location_link TEXT,dedupe_key TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,user_id,dedupe_key),FOREIGN KEY(tenant_id,user_id) REFERENCES users(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,trip_id) REFERENCES trips(tenant_id,id) ON DELETE CASCADE);
CREATE INDEX stop_route_idx ON student_stops(tenant_id,route_id);
CREATE INDEX event_trip_idx ON trip_events(tenant_id,trip_id,created_at);
CREATE INDEX notification_user_idx ON notifications(tenant_id,user_id,created_at);
-- Defense in depth; transactions set the authenticated tenant locally. This covers
-- owner accounts as well (FORCE); production app credentials must not be superuser.
ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenants FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_scope ON tenants USING(id::text=current_setting('app.tenant_id',true) OR current_setting('app.platform',true)='true');
DO $$DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['users','driver_verifications','document_blobs','vehicles','routes','student_stops','daily_attendance','trips','trip_events','fee_transactions','sos_events','notifications'] LOOP
 EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
 EXECUTE format('CREATE POLICY tenant_scope ON %I USING (tenant_id::text=current_setting(''app.tenant_id'',true) OR current_setting(''app.platform'',true)=''true'')',t);
END LOOP;END$$;
